namespace ghidra.app.plugin.core.datamgr;

using static org.junit.Assert;



using org.junit;
using org.junit;

using ghidra.app.plugin.core.analysis;
using ghidra.app.services;
using ghidra.framework;
using ghidra.program.database;
using ghidra.program.database;
using ghidra.program.model.dtarchive;
using ghidra.test;
using ghidra.test;
using ghidra.util.task;
using utilities.util;

public class ArchiveRemappedHeadlessTest : AbstractGhidraHeadlessIntegrationTest {

	private ProgramDB program;

	private DataTypeManagerService service;

	private File win32ArchiveDir;
	private File vs12ArchiveFile;
	private File vs9ArchiveFile;

	/* @Before */
	public void setUp()
    {

		// Create windows_VS9 archive copy before DataTypeManagerHandler initializes 
		// static list of known archives
		win32ArchiveDir =
			Application.getModuleDataSubDirectory("Base", "typeinfo/win32").getFile(false);
		assertNotNull(win32ArchiveDir);
		vs12ArchiveFile = new File(win32ArchiveDir, "windows_vs12_32.gdt");
		assertTrue("windows_vs12_32.gdt not found", vs12ArchiveFile.isFile());
		vs9ArchiveFile = new File(win32ArchiveDir, "windows_VS9.gdt");
		vs9ArchiveFile.deleteOnExit();
		FileUtilities.copyFile(vs12ArchiveFile, vs9ArchiveFile, false, TaskMonitor.DUMMY);

		program = buildProgram();

		// Headless data type service supplied by AutoAnalysisManager
		AutoAnalysisManager analysisManager = AutoAnalysisManager.getAnalysisManager(program);
		service = analysisManager.getDataTypeManagerService();
		assertNotNull(service);
		assertNull(analysisManager.getAnalysisTool());

	}

	private ProgramDB buildProgram()
    {
		ProgramBuilder builder = new ToyProgramBuilder();
		return builder.getProgram();
	}

	/* @Test */
	public void testGetRemappedArchive()
    {

		FileDataTypeArchive vs9Archive = service.openFileArchive("windows_VS9", TaskMonitor.DUMMY);
		assertNotNull(vs9Archive);
		try {
			assertEquals("windows_VS9", vs9Archive.getName());
		}
		finally {
			service.closeArchive(vs9Archive);
		}

		// Remove archive to force use of remapping
		vs9ArchiveFile.delete();
		assertFalse("windows_VS9.gdt should not exist", vs9ArchiveFile.exists());

		FileDataTypeArchive vs12Archive = service.openFileArchive("windows_VS9", TaskMonitor.DUMMY);
		assertNotNull(vs12Archive);
		try {
			assertEquals("windows_vs12_32", vs12Archive.getName());
		}
		finally {
			service.closeArchive(vs12Archive);
		}
	}

}
